export function formatRelative(date, now = new Date()) {
  const target = toDate(date)
  const reference = toDate(now)
  const days = signedDifferenceInDays(reference, target)

  if (days === 0) {
    const diffMs = target - reference
    const absSeconds = Math.abs(Math.round(diffMs / 1000))

    if (absSeconds < 60) return "just now"

    const absMinutes = Math.floor(absSeconds / 60)
    if (absMinutes < 60) {
      return diffMs < 0 ? `${absMinutes} minute${absMinutes === 1 ? "" : "s"} ago` : `in ${absMinutes} minute${absMinutes === 1 ? "" : "s"}`
